//! gRPC (-Dgrpc): services generated by zig-protobuf, served through the
//! router over gRPC on HTTP/2, gRPC-Web, Connect, and REST with JSON
//! (`google.api.http` transcoding); and a client over
//! `anole.h2.ClientConnection`.
//!
//! Serving: implement the generated methods as
//! `fn (call: *anole.grpc.Call, request) !Response` and register them with
//! `app.grpc(pb.Greeter, .{ .SayHello = sayHello })` (or `register` on a
//! router of your own). `app.grpcHealth()` adds grpc.health.v1. The wire
//! pieces (frames, status, metadata, deadlines, compression names) are
//! copied from grpc-lite.
const std = @import("std");
const features = @import("build_options");

// The wire pieces; the server, client and tests import them directly.
const frame = @import("frame.zig");
const status = @import("status.zig");
const metadata = @import("metadata.zig");
const deadline = @import("deadline.zig");

/// A call's outcome: a code and a message.
pub const Status = status.Status;
/// A gRPC status code (`.not_found`, `.invalid_argument`...).
pub const Code = status.Code;
/// A list of metadata pairs.
pub const Metadata = metadata.Metadata;
/// identity or gzip, as grpc-encoding names them.
pub const Compression = @import("compression.zig").Compression;

const server = @import("server.zig");
/// One call as its handler sees it: metadata, deadline, arena, status.
pub const Call = server.Call;
/// Registers a generated service's methods on a router;
/// `app.grpc(Service, impl)` does it for an `App` or `Server`.
pub const register = server.register;
/// `register` with `RegisterOptions`; `app.grpcWith` for an `App`.
pub const registerWith = server.registerWith;
/// Per registration: message size limit, data for the handlers,
/// transcoding, response compression, `no_wait`.
pub const RegisterOptions = server.RegisterOptions;
/// When response messages are gzipped: `.mirror` (the default),
/// `.accepted` or `.never`.
pub const ResponseCompression = server.ResponseCompression;
/// The request message limit of a registration without its own (4 MiB).
pub const default_max_message_size = server.default_max_message_size;
/// unary, server_streaming, client_streaming or bidi_streaming.
pub const MethodKind = server.MethodKind;
/// The wire protocol a call came in on (`Call.protocol()`).
pub const Protocol = server.Protocol;
/// How a call's messages are encoded (`Call.codec()`): proto or json.
pub const Codec = server.Codec;

/// The server's call machinery by bytes rather than generated types
/// (`begin`, `readPayload`, `writePayload`, `finish`), for Anole's C ABI,
/// whose services are implemented in another language. Not a stable API.
pub const serving = server;
/// JSON transcoding's templates, rules and request building, for the C
/// ABI's transcoded routes. Not a stable API.
pub const transcode = @import("transcode.zig");
/// Metadata keys and values: what may go out as gRPC metadata.
pub const metadata_keys = metadata;

/// The client: `Channel` over an `anole.h2.ClientConnection`, and
/// `Client(Service)` for typed calls.
const client = @import("client.zig");
/// A connection and authority that calls go out on.
pub const Channel = client.Channel;
/// A typed client for a generated service: `unary` and `stream`.
pub const Client = client.Client;
/// A call in progress: `send`, `closeSend`, `receive`, then `status`.
pub const ClientStream = client.Stream;
/// Per call: `timeout`, `metadata`, `compression`.
pub const CallOptions = client.CallOptions;
/// Opens a call by path ("/package.Service/Method") with message types
/// given, for code without a generated service.
pub const openCall = client.open;

/// grpc.health.v1.Health.
pub const health = @import("health.zig");
/// The health registry; `app.grpcHealth()` makes one for the server.
pub const Health = health.Health;

/// zig-protobuf (Arwalk/zig-protobuf, MIT): messages generated by
/// `protoc-gen-zig` import it as `protobuf`.
pub const protobuf = @import("protobuf");

test {
    _ = frame;
    _ = status;
    _ = metadata;
    _ = deadline;
    _ = @import("compression.zig");
    _ = server;
    _ = transcode;
    _ = @import("transcode_test.zig");
    _ = health;
    _ = client;
    if (features.http2) _ = @import("server_test.zig");
}
